/**
 * SourceChunkDetail
 *
 * P0-B — 인용 카드 원문보기 모달용 청크 상세 + dedup 된 연속 문맥.
 *
 * NotebookLM 패턴: 메인 청크 + 같은 volume 의 chunk_index 인접 ±N 청크들을
 * suffix-prefix overlap dedup 후 **하나의 연속 본문** 으로 합쳐 반환한다.
 * 사용자가 청크 경계의 끊김/중복 없이 자연스러운 reading flow 로 원문을
 * 확인할 수 있다. 프론트는 ``main_offset_start..main_offset_end`` 범위만
 * 시각적으로 강조 (좌측 brass border + accent 옅은 배경).
 *
 * Chunking artifact (overlap=150) 의 부산물이 백엔드에서 정리되므로 프론트는
 * 단순 substring slicing 만 수행.
 *
 * PoC 정리 (2026-04-29) — P1-B 4중 메타 (volume_no/delivered_at/delivered_place/
 * chapter_title + citation_label) 제거. 인덱싱 파이프라인이 4 필드를 채우게
 * 되면 재추가.
 */
export type SourceChunkDetail = {
    /**
     * Chunk Id
     *
     * Qdrant point id
     */
    chunk_id: string;
    /**
     * Chunk Index
     *
     * volume 내 메인 청크 순서 번호
     */
    chunk_index?: number;
    /**
     * Main Offset End
     *
     * merged_text 안에서 메인 청크 본문 끝 character offset (제외)
     */
    main_offset_end?: number;
    /**
     * Main Offset Start
     *
     * merged_text 안에서 메인 청크 본문 시작 character offset (포함)
     */
    main_offset_start?: number;
    /**
     * Merged Text
     *
     * 메인 + 인접 청크를 NFC 정규화 + suffix-prefix dedup 후 합친 연속 본문
     */
    merged_text?: string;
    /**
     * Sources
     *
     * 해당 청크가 속한 카테고리 key 목록
     */
    sources?: Array<string>;
    /**
     * Text
     *
     * 메인 청크 단독 본문 (legacy fallback 용)
     */
    text?: string;
    /**
     * Volume
     *
     * 원본 volume (파일명 또는 권명)
     */
    volume?: string;
};

